#!/usr/bin/env bash
# GPT Image 2 parts for the private knitted "Grace of Allah" (لطف الله) reel, LUTF-KNIT, for the owner's wife (@heal.ingthroughquran).
#   studio/remotion/src/lutfknit/gen.sh <job dir> <name> [<name> ...]      (names below; "round1", "round2" run a batch, 4 at a time)
# Only through the session's tagged gen2.sh wrapper (GPT Image 2 via the Codex shim), never another image model.
# Every character pose after the first is image-to-image from that character's first pose, so outfit and face stay the same.
set -u
JOB=$1; shift
G=$JOB/knit/gen; mkdir -p "$G"
GEN2=/private/tmp/claude-501/-Users-hammad-withhammad-video-pipeline/5fde070d-a498-45f3-88f9-d7769454f905/scratchpad/khair/gen2.sh
KNIT="a photograph of a handmade miniature diorama in which EVERYTHING is knitted, crocheted or felted from wool yarn: clearly visible knit stitches, stockinette and cable-knit textures, crochet details, felt, fuzzy wool fibres catching the light, like a stop-motion film set; soft cinematic light, gentle depth of field, rich saturated and varied colours"
DOLL="an amigurumi doll (crocheted wool, round soft head, embroidered eyes, eyebrows and mouth, rosy felt cheeks, yarn hair)"
GREEN="Full body, the whole figure inside the frame with a wide margin, centred, on a perfectly flat solid pure green #00FF00 background with no shadow, no floor, no other objects. No green anywhere on the figure. No text"
NOTEXT="No text, no letters, no writing, no logos, no watermark, no people unless asked"
PORT="Vertical 9:16 portrait image."

p() {   # name -> "prompt|ref"
  case $1 in
  # ---- backdrops and plates (no people) ----
  backdrop) echo "Wide landscape 3:2 image. $KNIT. A knitted countryside backdrop seen from a meadow: rolling hills of patchwork knitted fields in sage, olive, mustard, lavender and rust stripes, small round knitted trees and hedgerows, a felt farmhouse far away, fluffy cream felt clouds, a warm late-afternoon knitted sky from peach near the horizon to soft blue at the top, golden sunlight. Nothing in the foreground. $NOTEXT.|" ;;
  living) echo "$PORT $KNIT. A cosy knitted living room seen from a low camera near the floor, looking slightly up: a long three-seat crocheted sofa in deep teal across the lower middle of the frame, with mustard and coral knitted cushions, its seat empty; a small knitted walnut-brown side table at the LEFT end of the sofa with nothing on it; a patterned crochet rug in rose and cream; a window on the right with knitted cream curtains and warm sunlight; two framed knitted geometric eight-pointed-star patterns on the plaster-pink knitted wall (patterns only, no writing); the knitted ceiling visible across the top quarter with a round felt ceiling rose in the middle and NO ceiling fan and NO lamp hanging from it. $NOTEXT.|" ;;
  garage) echo "$PORT $KNIT. A knitted mechanic's garage seen at eye level from a low camera: the back wall is a knitted pegboard in mustard with felt tools hanging (spanners, hammer, screwdrivers), a long shelf of knitted paint cans and a red knitted oil can near the top right, a mustard knitted tool chest on the right, a big empty space in the middle of the floor for a car, a warm-grey knitted concrete floor with dark felt oil stains, a coiled black yarn air hose on the floor at the front left, a warm hanging work lamp. No car. $NOTEXT.|" ;;
  kitchen) echo "$PORT $KNIT. A knitted home kitchen in the evening: on the left a stove with a big shiny silver-yarn pressure cooker sitting on a blue felt flame with little white wool steam puffs from its valve; kitchen counters and cupboards knitted in plum and saffron with crochet tile backsplash in cream and teal; a window above the counter showing a deep-blue knitted night sky with a felt crescent moon; a crocheted pendant lamp hanging from the ceiling in the upper middle, glowing warm amber; on the right an open doorway to a dark corridor; a warm wooden-look knitted floor; nobody in the room, a clear standing space in front of the stove. $NOTEXT.|" ;;
  street) echo "$PORT $KNIT. A knitted city street at golden dusk seen from the pavement, the camera low behind a pedestrian's path: knitted brick buildings in terracotta and lavender with crochet windows on both sides, the right building wrapped in a wooden scaffolding made of knitted honey-brown beams, orange-and-white striped knitted traffic cones along the kerb, a grey knitted paving-stone pavement running away from the camera in the lower half, a soft lilac and peach knitted sky, a yellow knitted construction crane arm crossing the top of the frame with its cable going out of frame. The pavement is empty. $NOTEXT.|" ;;
  # ---- props on green ----
  fan) echo "Square image. $KNIT. One knitted ceiling fan seen from DIRECTLY BELOW, perfectly centred and perfectly symmetrical, flat-on like a top view: five wide rounded blades knitted in walnut-brown yarn with cream cable-knit edging, a round cream crochet motor hub in the centre with a small gold felt cap. Isolated on a perfectly flat solid pure green #00FF00 background, no shadow, nothing else. No text.|" ;;
  props) echo "Wide landscape 3:2 image. $KNIT. Four separate knitted props in a row with wide empty space between them: (1) a small crochet drinking glass in pale aqua yarn, half full, upright; (2) a small red knitted retro transistor radio with a cream felt speaker grille, two knobs and a silver yarn antenna; (3) a silver-grey knitted spanner (wrench), lying diagonally; (4) a small bunch of three silver-yarn keys on a ring with a round coral felt keychain. Isolated on a perfectly flat solid pure green #00FF00 background, no shadows, no other objects. No green on the props. No text.|" ;;
  car) echo "Wide landscape 3:2 image. $KNIT. One knitted vintage 1970s sedan car in 3/4 front-left view, slate-blue knitted body with a cream knitted roof stripe, silver yarn chrome bumpers and trim, black crochet tyres with silver hubcaps, round felt headlights, the whole car fully visible with margin around it. Isolated on a perfectly flat solid pure green #00FF00 background, no shadow, no floor. No green on the car. No text.|" ;;
  stands) echo "Wide landscape 3:2 image. $KNIT. Two identical tall red knitted car jack stands (axle stands: a tapered four-legged base and a vertical post with a cradle at the top), standing upright side by side with wide space between them, front view. Isolated on a perfectly flat solid pure green #00FF00 background, no shadow, no floor. No text.|" ;;
  beams) echo "Wide landscape 3:2 image. $KNIT. A bundle of six long knitted wooden construction beams in honey-brown yarn with knitted wood grain, stacked and tied with two red knitted straps, hanging horizontally from a big yellow knitted crane hook by two thick grey yarn cables that meet at the hook, the whole thing seen from slightly below, fully in frame. Isolated on a perfectly flat solid pure green #00FF00 background, no shadow. No text.|" ;;
  # ---- characters: pose 1 from text, later poses from pose 1 ----
  farmer1) echo "$PORT $KNIT. $DOLL: a chubby friendly farmer with short brown yarn hair and a short brown beard, a cream knitted shirt with rolled sleeves, cobalt-blue knitted dungarees with brass felt buttons, brown felt boots. Pose: sitting on the ground leaning back ASLEEP, eyes closed with a peaceful smile, legs stretched forward, both hands resting on his belly, seen from the front, slightly from his left. $GREEN.|" ;;
  farmer2) echo "$PORT The SAME amigurumi farmer doll as in the reference image (same face, hair, beard, cream shirt, cobalt-blue dungarees, brown boots, same knitted look), now sitting up on the ground AWAKE, eyes wide open, surprised, leaning and reaching with his right arm out to the right side of the image toward something on the ground. $GREEN.|farmer1" ;;
  farmer3) echo "$PORT The SAME amigurumi farmer doll as in the reference image (same face, hair, beard, cream shirt, cobalt-blue dungarees, brown boots), now STANDING upright facing the viewer, holding a small red knitted retro transistor radio with a cream felt grille and silver antenna in both hands at his belly, curious expression. $GREEN.|farmer1" ;;
  farmer4) echo "$PORT The SAME amigurumi farmer doll as in the reference image (same face, hair, beard, cream shirt, cobalt-blue dungarees, brown boots), now WALKING to the right in a side view (facing right, mid-stride), carrying the small red knitted radio in his hands, cheerful. $GREEN.|farmer1" ;;
  man1) echo "$PORT $KNIT. $DOLL: a slim young man with short black yarn hair and a neat short black beard, wearing light-grey knitted pyjamas (long sleeves, long trousers), barefoot. Pose: lying flat on his back ASLEEP in a horizontal pose, head on the LEFT and feet on the right, eyes closed, one hand on his chest, side view, as if lying on a sofa (but no sofa). Horizontal figure in the middle of the frame. $GREEN.|" ;;
  man2) echo "$PORT The SAME amigurumi young man doll as in the reference image (same face, black hair and beard, light-grey pyjamas, barefoot), now SITTING upright on an invisible seat with his legs hanging down, sleepy, rubbing one eye with his hand, 3/4 front view. $GREEN.|man1" ;;
  man3) echo "$PORT The SAME amigurumi young man doll as in the reference image (same face, black hair and beard, light-grey pyjamas, barefoot), now WALKING toward the viewer and to the LEFT of the image, mid-stride, looking down at the floor, 3/4 front view. $GREEN.|man1" ;;
  man4) echo "$PORT The SAME amigurumi young man doll as in the reference image (same face, black hair and beard, light-grey pyjamas, barefoot), now STANDING and SHOCKED, wide eyes, mouth open, both hands on his head, facing the viewer turned slightly to the right. $GREEN.|man1" ;;
  mech1) echo "$PORT $KNIT. $DOLL: a mechanic with curly dark-brown yarn hair and a short curly beard, navy-blue knitted overalls with a small orange felt patch on the chest, black felt boots. Pose: lying flat on his back on a low knitted creeper board (a flat board on small wheels), horizontal, head on the LEFT, feet on the right, holding a spanner up with one hand as if working under a car, side view. Horizontal figure in the middle of the frame. $GREEN.|" ;;
  mech2) echo "$PORT The SAME amigurumi mechanic doll as in the reference image (same face, curly hair and beard, navy overalls with orange patch, black boots), now SITTING on the floor (no board), propped on one hand, looking to the left of the image, surprised, side view facing left. $GREEN.|mech1" ;;
  mech3) echo "$PORT The SAME amigurumi mechanic doll as in the reference image (same face, curly hair and beard, navy overalls with orange patch, black boots), now STANDING upright facing the viewer, one hand on his chest, puzzled and relieved. $GREEN.|mech1" ;;
  mech4) echo "$PORT The SAME amigurumi mechanic doll as in the reference image (same face, curly hair and beard, navy overalls with orange patch, black boots), now STANDING and SHOCKED, leaning back, eyes wide, mouth wide open, both arms out at his sides, 3/4 view looking to the LEFT of the image. $GREEN.|mech1" ;;
  woman1) echo "$PORT $KNIT. $DOLL: a young woman wearing a modest long burgundy-red knitted dress with long sleeves, a black knitted hijab that covers her hair, ears and neck, and a cream crochet apron tied at the back. Pose: standing seen from BEHIND, slightly turned to the left (her back and the apron bow to the viewer), stirring with a wooden spoon held in front of her at chest height. $GREEN.|" ;;
  woman2) echo "$PORT The SAME amigurumi woman doll as in the reference image (same black hijab covering hair and neck, burgundy-red long dress, cream crochet apron), now standing in SIDE VIEW facing the RIGHT of the image, looking up and to the right, curious and puzzled. $GREEN.|woman1" ;;
  woman3) echo "$PORT The SAME amigurumi woman doll as in the reference image (same black hijab covering hair and neck, burgundy-red long dress, cream crochet apron tied at the back), now WALKING away from the viewer to the right, seen from behind, mid-stride. $GREEN.|woman1" ;;
  woman4) echo "$PORT The SAME amigurumi woman doll as in the reference image (same black hijab covering hair and neck, burgundy-red long dress, cream crochet apron), now standing FACING the viewer, SHOCKED, wide eyes and open mouth, both hands on her cheeks. $GREEN.|woman1" ;;
  boy1) echo "$PORT $KNIT. $DOLL: a teenage boy with wavy brown yarn hair, a royal-blue knitted hoodie, charcoal knitted trousers and white felt sneakers, a small bunch of silver-yarn keys hanging from his belt loop. Pose: WALKING AWAY from the viewer, seen from BEHIND, looking down at a small black felt phone in his hands, mid-stride. $GREEN.|" ;;
  boy1b) echo "$PORT The SAME image as the reference image, the same amigurumi boy doll in the same pose and framing (seen from behind, walking, looking at his phone), but WITHOUT any keys: his belt loop and trouser pocket are empty. $GREEN.|boy1" ;;
  boy2) echo "$PORT The SAME amigurumi boy doll as in the reference image (same wavy brown hair, royal-blue hoodie, charcoal trousers, white sneakers), now BENDING DOWN to pick something up from the ground with his right hand, knees bent, side view facing the RIGHT of the image, phone in his left hand. $GREEN.|boy1" ;;
  boy3) echo "$PORT The SAME amigurumi boy doll as in the reference image (same wavy brown hair, royal-blue hoodie, charcoal trousers, white sneakers), now JUMPING BACKWARD in fright, both arms up in front of his face, leaning back, side view facing the RIGHT of the image. $GREEN.|boy1" ;;
  boy4) echo "$PORT The SAME amigurumi boy doll as in the reference image (same wavy brown hair, royal-blue hoodie, charcoal trousers, white sneakers), now SITTING on the ground, leaning back on his hands, legs out, shocked, wide eyes and open mouth, 3/4 front view facing the RIGHT of the image. $GREEN.|boy1" ;;
  boyclose) echo "$PORT $KNIT. Close-up portrait of the SAME amigurumi boy doll as in the reference image (same wavy brown yarn hair and royal-blue knitted hoodie), head and shoulders filling the lower two thirds of the frame, SHOCKED: wide embroidered eyes, eyebrows raised, mouth open; behind him, out of focus, a knitted city street with fallen honey-brown knitted beams, a yellow knitted crane hook and soft clouds of white wool dust, golden dusk light. $NOTEXT.|boy1" ;;
  # ---- after plates: the same rooms after the near miss (image-to-image) ----
  livingafter) echo "$PORT The SAME knitted living room as in the reference image, same camera, same sofa, cushions, rug, window, frames and colours, but now a knitted ceiling fan (walnut-brown knitted blades with cream edging, cream crochet hub) has CRASHED down onto the MIDDLE of the sofa seat: the blades bent and splayed across the cushions, the downrod snapped, a torn hole in the ceiling above where the ceiling rose was with loose yarn strands hanging, little clumps of white wool fluff and plaster-pink yarn bits scattered on the sofa and rug. Nobody in the room. $NOTEXT.|living" ;;
  kitchenafter) echo "$PORT The SAME knitted kitchen as in the reference image, same camera, same cupboards, window and doorway, but just after the pressure cooker EXPLODED: the cooker body is blackened and split open on the stove, its lid is gone, splashes of orange-red crochet stew are spattered over the backsplash, the counter and the floor, soft white bouclé wool steam clouds rise from the stove, the pendant lamp still glowing. Nobody in the room. $NOTEXT.|kitchen" ;;
  *) echo "" ;;
  esac
}

one() {
  local spec prompt ref out
  spec=$(p "$1"); [ -n "$spec" ] || { echo "unknown $1"; return 2; }
  prompt=${spec%|*}; ref=${spec##*|}; out=$G/$1.png
  [ -s "$out" ] && { echo "have $1"; return 0; }
  for try in 1 2; do
    if [ -n "$ref" ]; then bash "$GEN2" "$out" "$prompt" "$G/$ref.png" >/dev/null 2>&1; else bash "$GEN2" "$out" "$prompt" >/dev/null 2>&1; fi
    [ -s "$out" ] && { echo "ok $1"; return 0; }
    echo "retry $1 ($try)"
  done
  echo "FAIL $1"; return 1
}

batch() { local n=0; for x in "$@"; do one "$x" & n=$((n + 1)); if [ $((n % 4)) -eq 0 ]; then wait; fi; done; wait; }

for a in "$@"; do
  case $a in
    round1) batch backdrop living garage kitchen street farmer1 man1 mech1 woman1 boy1 fan props car stands beams ;;
    round2) batch farmer2 farmer3 farmer4 man2 man3 man4 mech2 mech3 mech4 woman2 woman3 woman4 boy2 boy3 boy4 boyclose livingafter kitchenafter ;;
    *) one "$a" ;;
  esac
done
